--
-- Name: daily_game_stats; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.daily_game_stats AS
 SELECT ((b.placed_at AT TIME ZONE 'UTC'::text))::date AS stat_date,
    s.game_id,
    (count(*))::integer AS total_bets,
    (count(DISTINCT s.player_id))::integer AS unique_players,
    (sum(b.stake))::numeric(14,2) AS total_staked,
    (sum(b.payout))::numeric(14,2) AS total_paid,
    ((sum(b.stake) - sum(b.payout)))::numeric(14,2) AS ggr
   FROM (public.bets b
     JOIN public.game_sessions s ON ((s.id = b.session_id)))
  GROUP BY (((b.placed_at AT TIME ZONE 'UTC'::text))::date), s.game_id
  WITH NO DATA;


